use vstd::prelude::*;
use vstd::string::*;

verus! {

// ASCII values for digits
spec const ASCII_ZERO: u8 = 48u8;
spec const ASCII_NINE: u8 = 57u8;

// Specification function for checking if a character is an ASCII digit
spec fn is_ascii_digit_spec(c: char) -> bool {
    let code = c as u8;
    ASCII_ZERO <= code && code <= ASCII_NINE
}

fn is_ascii_digit(c: char) -> (result: bool)
    ensures
        result == is_ascii_digit_spec(c),
{
    // Check if the character is between '0' and '9' inclusive
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> (result: bool)
    ensures
        result == forall|i: int| 0 <= i < s.len() ==> is_ascii_digit_spec(s.char_at(i)),
{
    // For empty string, return true (vacuously true)
    // Check each character in the string
    
    let mut chars = s.chars();
    let mut idx: usize = 0;
    
    while let Some(c) = chars.next()
        invariant
            0 <= idx <= s.len(),
            chars.len() == s.len() - idx,
            forall|i: int| 0 <= i < idx ==> is_ascii_digit_spec(s.char_at(i)),
    {
        if !is_ascii_digit(c) {
            assert(!is_ascii_digit_spec(c));
            return false;
        }
        assert(is_ascii_digit_spec(c));
        idx = idx + 1;
    }
    
    true
}

}
